/// A collider's place in DetPhysics' sort-and-sweep: its bounding-box minimum
/// on the sweep axis, then its shape (circle, box, rounded rect), then its
/// index in that shape's PhysicsBodyList (AABBXComparer.cs:6-19). The list
/// appends and closes gaps in order (PhysicsBodyList.cs:39-67), so the index is
/// registration order among the live colliders, which one kind's rows keep.
type SweepRank = (Fix, u32, usize);

/// What `gate_published_source_abilities` reads off the live slimes, once per
/// observation.
struct SourceGate {
    held: HeldAbilities,
    live_forms: [u32; MAX_BODIES * 3],
    any_platform: bool,
    drill_hitbox_layer: u32,
}

/// The abilities in the listed slimes' slots (`live_slime_abilities`): one bit
/// per ability id for each body, and the body's player id.
struct HeldAbilities {
    ids: [u32; MAX_BODIES],
    bits: [u64; MAX_BODIES],
    count: usize,
}

impl HeldAbilities {
    /// `player_holds`: whether any listed body of player `id` holds
    /// `ability`, a real ability (never `ABILITY_NULL`).
    fn holds(&self, id: u32, ability: u32) -> bool {
        debug_assert!(ability != ABILITY_NULL && ability < 64);
        let bit = 1u64 << (ability & 63);
        self.ids[..self.count].iter().zip(&self.bits[..self.count]).any(|(&body, &bits)| body == id && bits & bit != 0)
    }

    /// Whether any listed body holds `ability`.
    fn any(&self, ability: u32) -> bool {
        debug_assert!(ability != ABILITY_NULL && ability < 64);
        let bit = 1u64 << (ability & 63);
        self.bits[..self.count].iter().any(|&bits| bits & bit != 0)
    }
}

fn sweep_rank(entities: &[CEntity], min: Fix, entity: Option<usize>) -> SweepRank {
    let entity = entity.unwrap_or(usize::MAX);
    (min, entities.get(entity).map_or(u32::MAX, |row| row.kind), entity)
}

/// Appends an entity row together with its collider's Box.inverseExtents
/// (Box.cs:30-41), zero for a row with no box: the one way a row is added, so
/// every row has its entry.
fn push_entity(entities: &mut Vec<CEntity>, table: &mut Vec<Vec2>, row: CEntity, inverse_extents: Vec2) -> usize {
    entities.push(row);
    table.push(inverse_extents);
    entities.len() - 1
}

/// Records the Box.inverseExtents of box row `entity` (Box.cs:30-41).
fn set_inverse_extents(table: &mut [Vec2], entity: usize, value: Vec2) {
    table[entity] = value;
}

/// SortAndSweep reaches a pair at its later collider and walks the earlier ones
/// in sort order, so pairs come out by the later rank, then the earlier
/// (DetPhysics.cs:2169-2231).
fn sweep_pair(a: SweepRank, b: SweepRank) -> (SweepRank, SweepRank) {
    if a > b { (a, b) } else { (b, a) }
}

