/// A live arrow (Arrow.cs + Projectile.cs): a ballistic projectile that kills
/// players on contact and sticks to supported non-player geometry. Ordinary
/// PlayerBody hurtboxes do not satisfy Arrow's `BoplBody` check, so an arrow
/// keeps flying after killing a slime. A stuck arrow's collider is destroyed
/// in the .NET sim, so it vanishes from the observation; here the slot is
/// simply freed.
/// A landed arrow. Arrow.OnCollide parents it to the hit collider's own
/// FixTransform and destroys all of it but its Arrow updatable, which stays
/// a child of that GameObject (Arrow.cs:100, 124-128).
#[derive(Clone, Copy)]
pub struct LandedArrow {
    /// A HierarchyNumber of the parent's own: a wall's row, or the first of
    /// a spawned object's updatables.
    pub parent: u32,
    /// Its Arrow updatable's HierarchyNumber.
    pub hierarchy: u32,
    /// The pass in which a landing past 80 children DestroyFix'd it. It
    /// stays a child until the Updater's end-of-pass DestroyImmediate
    /// (Arrow.cs:104-118, Updater.cs:339-344).
    pub trimmed: Option<u32>,
}

/// The first HierarchyNumber of an object whose prefab registered after
/// `base` others: EndRegisterPrefab numbers its updatables from one past
/// prefabsAdded (Updater.cs:143-152).
fn spawned_hierarchy(base: u32) -> u32 {
    100_000_000 + base + 1
}

/// A MagnetGun: the ability instance in a player's slot. A newer instance
/// in the slot, its generation turned over, leaves it IsDestroyed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MagnetGun {
    pub player: usize,
    pub slot: usize,
    pub generation: u32,
}

/// BoplBody's hold: magnetGunHolder, the MagnetGun that last held the body,
/// and framesUntilDrop (BoplBody.cs:42-45, 285-331).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Hold {
    pub holder: Option<MagnetGun>,
    frames: i8,
}

impl Default for Hold {
    fn default() -> Self {
        Self { holder: None, frames: -1 }
    }
}

impl Hold {
    /// BoplBody.Hold.
    fn hold(&mut self, frames: i8, holder: MagnetGun) {
        self.holder = Some(holder);
        self.frames = frames;
    }

    /// BoplBody.Drop.
    fn release(&mut self) {
        *self = Self::default();
    }

    /// BoplBody.IsBeingHeld.
    fn held(&self) -> bool {
        self.frames >= 0
    }

    /// BoplBody.UpdateSim's countdown: it drops the body when it reaches
    /// zero. Below zero it only keeps counting, which nothing reads.
    fn update_sim(&mut self) {
        if self.frames >= 0 {
            self.frames -= 1;
            if self.frames == 0 {
                self.release();
            }
        }
    }
}

#[derive(Clone, Copy, Default)]
pub struct Arrow {
    pub active: bool,
    pub appended: u32,
    pub hierarchy_base: u32,
    /// Instantiated this tick, but not added to DetPhysics/updatables until
    /// the next scheduler pass.
    pub registered: bool,
    pub id: u32,
    /// Owning player id (1-based).
    pub owner: u32,
    /// The BowTransform whose Arrows ring holds it: its slot and that slot's
    /// ability generation. A Duplicator copy is in no ring.
    pub bow: Option<(usize, u32)>,
    pub entity: Option<usize>,
    pub position: Vec2,
    /// Live FixTransform scale. Ordinary Bow arrows start at one; Duplicator
    /// copies the source transform scale exactly.
    pub scale: Fix,
    /// DPhysicsCircle.radius, which the Scale setter multiplies by
    /// `(1 / old) * new` (DPhysicsCircle.cs:214-221).
    pub collider_radius: Fix,
    /// BoplBody.prevScale: the scale the DetPhysics mass last followed.
    /// BoplBody.UpdateSim divides the inverse mass and inertia by each
    /// scale change, so a grown arrow hits harder.
    pub mass_scale: Fix,
    /// Pass in which a ScaleChanger, newer than this arrow's BoplBody,
    /// changed `scale`: the mass follows on the next pass.
    pub scaled_tick: u32,
    pub inverse_mass: Fix,
    pub inverse_inertia: Fix,
    pub velocity: Vec2,
    pub force: Vec2,
    pub angular_velocity: Fix,
    /// Arrow.UpdateSim aligns the sprite before DetPhysics applies gravity.
    pub rotation: Fix,
    pub time_passed: Fix,
    /// Projectile.DelayedEnableHurtOwner: 5 units of travel time.
    pub hurt_owner_after: Fix,
    pub can_hurt_owner: bool,
    pub hold: Hold,
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
}

impl Arrow {
    /// The DetPhysics body, with this arrow's own scaled mass.
    fn body(&self, base: &Body) -> Body {
        Body {
            velocity: self.velocity,
            orientation: self.rotation,
            angular_velocity: self.angular_velocity,
            inverse_mass: self.inverse_mass,
            inverse_inertia: self.inverse_inertia,
            ..*base
        }
    }

    /// Arrow.UpdateSim on a body nothing holds: its up follows the velocity
    /// (Arrow.cs:66-74).
    fn align_to_velocity(&mut self) {
        let speed = self.velocity.length();
        let up = if speed == Fix::ZERO { Vec2::UP } else { self.velocity / speed };
        // DetPhysics.IntegrateBody wraps the orientation into [0, 2pi)
        // (DetPhysics.cs:1645) and SyncGameObject writes it back to the
        // arrow's FixTransform, so a straight shot reads 0, not 2pi.
        self.rotation = up.perp_cw().normalized_angle();
    }

    /// BoplBody.UpdateSim divides the inverse mass and inertia by a scale
    /// change since it last ran.
    fn sync_mass(&mut self) {
        if self.scale != self.mass_scale
            && self.inverse_mass != Fix::ZERO
            && self.inverse_inertia != Fix::ZERO
        {
            let ratio = self.mass_scale / self.scale;
            self.inverse_mass *= ratio;
            self.inverse_inertia *= ratio;
            self.mass_scale = self.scale;
        }
    }
}

/// A live `DynamicAbilityPickup`. The vector is bounded by the authored three
/// spawns and retains its capacity across resets.
#[derive(Clone, Copy, Default)]
pub struct AbilityPickup {
    pub active: bool,
    pub appended: u32,
    pub hierarchy_base: u32,
    pub entity: Option<usize>,
    /// AbilityIcons index; the full catalog is dense and uses the same ids.
    pub ability: u32,
    /// Root FixTransform position. The collider centre includes `pickup.offset`.
    pub position: Vec2,
    pub scale: Fix,
    /// Live FixTransform.offset and DPhysicsCircle.radius. Each Scale write
    /// compounds them (FixTransform.cs:102, DPhysicsCircle.cs:216-220).
    pub offset: Vec2,
    pub radius: Fix,
    /// Where DetPhysics last synced the circle: at ManualInit, then at each
    /// Simulate. UpdateSim's vibration moves the FixTransform, but the casts
    /// of a later updater in the same pass still meet the circle here.
    pub synced_center: Vec2,
    pub body: Body,
    pub hold: Hold,
    pub enabled: bool,
    pub time_passed: Fix,
    pub time_since_swap: Fix,
    pub previous_vibration: Vec2,
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
}

impl AbilityPickup {
    /// `Vec2.ComplexMul(fixTrans.right, fixTrans.offset)`: the offset turned
    /// by the rotation.
    fn turned_offset(&self) -> Vec2 {
        Vec2::angle(self.body.orientation).complex_mul(self.offset)
    }

    /// SyncAllPhysicsObjectsToFixTransformPosition and UpdatePhysicsPositions:
    /// the collider's centre takes the FixTransform position plus the turned
    /// offset (DetPhysics.cs:2514, DPhysicsCircle.cs:318).
    fn sync_collider_to_fix_trans(&mut self) {
        self.synced_center = self.position + self.turned_offset();
    }

    /// SyncGameObject: the FixTransform goes back from the collider's centre
    /// by the offset turned to the new rotation (DetPhysics.cs:1654-1655).
    fn sync_fix_trans_to_collider(&mut self) {
        self.position = self.synced_center - self.turned_offset();
    }
}

/// Shared `ThrowItem2` payload state. Grenade is the first consumer; Smoke,
/// Poke Ball, Tack, and Mjolnir use the same held-item/throw lifecycle.
#[derive(Clone, Copy, Default)]
pub struct ThrownItem {
    pub active: bool,
    pub id: u32,
    pub owner: usize,
    pub ability: u32,
    pub ability_slot: usize,
    pub ability_generation: u32,
    pub appended: u32,
    pub hierarchy_base: u32,
    pub entity: Option<usize>,
    /// A ManualInit performed from a DetPhysics callback joins the collider
    /// registry immediately but cannot enter the already-built manifold set.
    pub callback_registered_tick: u32,
    pub position: Vec2,
    pub body: Body,
    /// Live DPhysicsCircle/FixTransform scale. `body_scale` is the value the
    /// earlier BoplBody updater has consumed; a late ScaleChanger mutation is
    /// reflected in mass on the following updater pass, as in the source.
    pub scale: Fix,
    pub body_scale: Fix,
    /// DPhysicsCircle's live radius. Scale mutates this incrementally through
    /// `(1 / old_scale) * new_scale`, retaining its fixed-point history.
    pub collider_radius: Fix,
    pub fuse: Fix,
    pub hurt_owner_delay: Fix,
    pub detonates_on_owner: bool,
    pub age: Fix,
    pub launched: bool,
    pub settled: bool,
    pub owner_clear: bool,
    pub settle_position: Vec2,
    /// Ability-specific phase (Mjolnir: 0 outbound, 1 returning).
    pub phase: u8,
    /// Mjolnir's allocation-free equivalent of `HashSet<int> alreadyKilled`.
    pub killed_players: u8,
    /// Shockwave.UpdateSim follows Mjolnir.UpdateSim in runtime hierarchy,
    /// while Shockwave.Init runs before the updater pass. Retain only the
    /// regular-pass impulse until Mjolnir has updated its recall velocity.
    pub pending_gust_impulse: Vec2,
    /// Mine.Init/LateUpdateSim state. Keeping it in the pooled item avoids a
    /// side allocation for every autonomous mine.
    pub random_offset: Fix,
    pub time_since_anticipation: Fix,
    pub prev_chase_dir: Vec2,
    pub prev_rand_vector: Vec2,
    pub prev_velocity_change: Vec2,
    /// Where ManualInit registered the collider: at the spawn, or in the
    /// hand when Fire throws a payload spawned this pass. DetPhysics keeps it
    /// there until the next Simulate.
    pub synced_center: Vec2,
    /// Poke Ball capture state. `None` is the ordinary flying/fizzle phase.
    pub capture_victim: Option<usize>,
    pub capture_victim_is_clone: bool,
    /// The captured slime's `slime_instance`.
    pub capture_victim_instance: u32,
    pub capture_left: Fix,
    /// `DetPhysics.duplicatedObjects`: Duplicator copies count down from 1800
    /// before ordinary updaters run.
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
    pub hold: Hold,
}

impl ThrownItem {
    /// Grenade.hasBeenThrown on the Grenade and Smoke payloads, which carry
    /// the Grenade component. Once set, ThrowItem2 still references the
    /// payload but neither holds it in the hand nor throws it again
    /// (ThrowItem2.cs:221, 282).
    fn has_been_thrown(&self) -> bool {
        matches!(self.ability, ABILITY_GRENADE | ABILITY_SMOKE) && self.launched
    }

    /// BoplBody.UpdateSim's rescale: `inverseMass *= prevScale / scale` once
    /// the collider's scale moved (BoplBody.cs:332-344).
    fn rescale_mass(&mut self) {
        if self.scale == self.body_scale
            || self.body.inverse_mass == Fix::ZERO
            || self.body.inverse_inertia == Fix::ZERO
        {
            return;
        }
        let ratio = self.body_scale / self.scale;
        self.body.inverse_mass *= ratio;
        self.body.inverse_inertia *= ratio;
        self.body_scale = self.scale;
    }
}

