/// A SlimeController's Player.SetPosition this pass: a body's turn, or an
/// abilityless clone's OldUpdate and the position it set; or the destruction
/// of the SlimeController with that row id, after which it loses any
/// comparison (Player.comparePriority). A dying body's slot can be refilled
/// by a promoted clone, so its Gone keeps the position it set.
#[derive(Clone, Copy, PartialEq)]
enum PositionCall {
    Body(usize),
    Clone(usize, Vec2),
    Gone(Option<Vec2>),
}

/// A SlimeController or form a Mjolnir hit: a body, or an abilityless clone.
#[derive(Clone, Copy)]
enum MjolnirVictim {
    Body(usize),
    Clone(usize),
}

/// The player id of a body index, which objects store as their owner.
fn player_id(players: &[PlayerSlot], body: usize) -> u32 {
    players[body].base.id
}

impl GrenadeExplosion {
    fn killer(&self, players: &[PlayerSlot]) -> u32 {
        if self.credited_owner { player_id(players, self.owner) } else { 0 }
    }
}

/// SparkShot's guided projectile. The projectile remains live after the
/// ability form exits and switches from stabilized flight to its own thrust.
#[derive(Clone, Copy, Default)]
pub struct GuidedMissile {
    pub active: bool,
    pub registered: bool,
    pub appended: u32,
    pub hierarchy_base: u32,
    pub entity: Option<usize>,
    pub owner: usize,
    pub position: Vec2,
    /// The PhysicsBody; its orientation is the DetPhysics box's.
    pub body: Body,
    /// The FixTransform's orientation. SparkShot and MagnetGun write it
    /// through BoplBody.up, which leaves the PhysicsBody and box alone until
    /// DetPhysics next syncs them to it.
    pub transform: Orientation,
    pub scale: Fix,
    /// The Spark DPhysicsBox's |One / startExtents|, which Init copies into
    /// its row's inverseExtents. A Scale write before Init lands here
    /// (DPhysicsBox.cs:212-214); later ones divide the row's.
    pub start_inverse_extents: Vec2,
    pub instability_ticks: u32,
    /// `DetPhysics.duplicatedObjects` state for Missile copies. Keeping this
    /// on the pooled projectile avoids a side allocation in the hot path.
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
    pub hold: Hold,
}

impl GuidedMissile {
    /// The box and PhysicsBody take the FixTransform's rotation
    /// (DPhysicsBox.UpdatePhysicsPositions, DPhysicsBox.cs:276-291; the same
    /// as SyncAllPhysicsObjectsToFixTransformPosition, DetPhysics.cs:2519-2527).
    fn sync_body_to_transform(&mut self) {
        self.body.orientation = self.transform.rotation();
    }

    /// The Spark box, rebuilt from the inverseExtents its row holds, or from
    /// startExtents before Init.
    fn collider(&self, table: &[Vec2]) -> OrientedBox {
        let inverse_extents = match self.entity {
            Some(entity) if self.registered => table[entity],
            _ => self.start_inverse_extents,
        };
        stored_box(self.position, Vec2::angle(self.body.orientation), inverse_extents)
    }
}

