/// SpikeAttack's manually initialized box, attached to a rounded platform as
/// a DetPhysics composite child. Positions are stored in the platform body's
/// frame so platform motion never requires a separate rigid-body integration.
#[derive(Clone, Copy, Default)]
pub struct SpawnedSpike {
    pub active: bool,
    /// When it joined its platform's composite, in that platform's
    /// `attach_count`. CreateMultiComposite re-attaches in that order.
    pub attach_order: u32,
    /// The owning player's ability slot for a cast spike. Duplicator copies
    /// are not referenced by a Spike ability instance.
    pub owner_slot: Option<(usize, usize)>,
    /// MachoThrow2 detached this box from its composite while the boulder is
    /// still represented only by the player's dummy sprite.
    pub macho_carried: bool,
    /// The pass it was placed on its platform: cast, copied, or re-attached
    /// by MachoThrow2. RepositionOnParent reads the placement normal then.
    pub placed_tick: u32,
    pub appended: u32,
    pub hierarchy_base: u32,
    pub entity: Option<usize>,
    pub platform_index: usize,
    pub local: Fix,
    pub relative_center: Vec2,
    /// The placement normal SpikeAttack.Initialize gave a cast spike. On the
    /// cast pass its hitbox still carries it, so a RepositionOnParent re-derives
    /// the offset from it on the platform's current shape, even after a
    /// composite rebuild refit the offset in between.
    pub placed_up: Option<Vec2>,
    pub relative_rotation: Fix,
    pub collider_center: Vec2,
    /// FixTransform.position and rotation as SyncGameObject last wrote them,
    /// or as a writer that set the transform itself left them
    /// (DetPhysics.cs:1652-1656, 3172-3192). A composite's
    /// UpdatePhysicsPositions and a Scale write move only the collider
    /// (DetPhysics.cs:2467-2496, DPhysicsBox.cs:207-208, SpikeAttack.cs:144-158).
    pub transform_position: Vec2,
    pub transform_rotation: Fix,
    pub surface_offset: Fix,
    /// SpikeAttack.fixedOffset, the offset Initialize was handed: Spike's
    /// 0.5 for a cast, ShootDuplicator's 0.75 for a copy, and MachoThrow2's
    /// re-measured offset for a boulder re-attach. UpdatePosition adds it
    /// to the DownThrust curve.
    pub fixed_offset: Fix,
    pub scale: Fix,
    /// FixTransform.offset. SetScale_DPhysicsOnly compounds each rescale as
    /// `offset *= new / old`.
    pub collider_offset: Vec2,
    pub time: Fix,
    pub body: Body,
    /// SpikeAttack.pushedThisFrame: only the first knock of a pass also
    /// pushes the spike's own platform. UpdateSim clears it.
    pub pushed_this_frame: bool,
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
}

impl SpawnedSpike {
    /// SyncGameObject's write of this child's FixTransform from its box on a
    /// platform turned by `parent_rotation`.
    fn sync_transform(&mut self, parent_rotation: Fix) {
        self.transform_rotation = parent_rotation + self.relative_rotation;
        self.transform_position = transform_root(self.collider_center, self.collider_offset, self.transform_rotation);
    }

    /// The box collider's inverseExtents, which its row holds. DPhysicsBox.Scale
    /// divides it by `(1 / old) * new`, so it is not `1 / (extents * scale)`.
    fn inverse_extents(&self, table: &[Vec2]) -> Vec2 {
        table[self.entity.expect("a registered spike")]
    }

    /// Box.SetRotation's `Vec2.right / inverseExtents.x` and `up / .y`.
    fn box_extents(&self, table: &[Vec2]) -> Vec2 {
        let inverse_extents = self.inverse_extents(table);
        Vec2::new(Fix::ONE / inverse_extents.x, Fix::ONE / inverse_extents.y)
    }
}

