/// One RocketEngine collider attached to a rounded-platform composite.
#[derive(Clone, Copy, Default)]
pub struct SpawnedEngine {
    pub active: bool,
    /// When it joined its platform's composite, in that platform's
    /// `attach_count`. CreateMultiComposite re-attaches in that order.
    pub attach_order: u32,
    /// MachoThrow2 detached this child from its platform composite and hid
    /// the GameObject while the replacement boulder is being animated.
    pub macho_carried: bool,
    pub appended: u32,
    pub owner: usize,
    pub ability_slot: usize,
    pub ability_generation: u32,
    pub hierarchy_base: u32,
    pub entity: Option<usize>,
    pub platform_index: usize,
    pub local: Fix,
    pub relative_center: Vec2,
    pub relative_rotation: Fix,
    pub collider_center: Vec2,
    pub collider_rotation: Fix,
    /// The FixTransform pose SyncGameObject last wrote from the collider
    /// (DetPhysics.cs:1653-1656, 3172-3192). A composite's
    /// UpdatePhysicsPositions re-places the collider without it
    /// (DetPhysics.cs:2467-2496), so updaters reading the transform keep it.
    pub transform_position: Vec2,
    pub transform_rotation: Fix,
    pub surface_offset: Fix,
    pub scale: Fix,
    /// FixTransform.offset, compounded like SpawnedSpike::collider_offset.
    pub collider_offset: Vec2,
    /// RocketEngine.prevScale: component offsets adopt a DPhysics scale write
    /// on the following RocketEngine updater pass.
    pub offset_scale: Fix,
    pub time: Fix,
    /// 0=start animation, 1=firing, 2=end animation, 3=off.
    pub phase: u32,
    pub ticks: u32,
    pub body: Body,
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
    /// FixTransform.up as PlaceRocketEngine set it, until the first physics
    /// sync replaces it with the body rotation's.
    pub placed_up: Option<Vec2>,
}

impl SpawnedEngine {
    /// SyncGameObject: the FixTransform takes the box's pose.
    fn sync_transform(&mut self) {
        self.transform_position = transform_root(self.collider_center, self.collider_offset, self.collider_rotation);
        self.transform_rotation = self.collider_rotation;
    }

    /// The box collider's inverseExtents, as in SpawnedSpike.
    fn inverse_extents(&self, table: &[Vec2]) -> Vec2 {
        table[self.entity.expect("a registered engine")]
    }

    /// Box.SetRotation's `Vec2.right / inverseExtents.x` and `up / .y`.
    fn box_extents(&self, table: &[Vec2]) -> Vec2 {
        let inverse_extents = self.inverse_extents(table);
        Vec2::new(Fix::ONE / inverse_extents.x, Fix::ONE / inverse_extents.y)
    }

    /// The rocket's box collider at its collider pose.
    fn rocket_box(&self, table: &[Vec2]) -> OrientedBox {
        let basis = Vec2::angle(self.collider_rotation);
        let extents = self.box_extents(table);
        OrientedBox {
            center: self.collider_center,
            right: basis * extents.x,
            up: (Vec2::UP * extents.y).complex_mul(basis),
            inverse_extents: self.inverse_extents(table),
        }
    }
}

/// One SimpleSparkNode circle and the optional lightning owned by the newer
/// endpoint of a connected pair.
#[derive(Clone, Copy, Default)]
