/// HitboxCombo.UpdateHitBoxPositionsAndScale for the active Drill slot's
/// boxes, at the pose `drill.hitbox_*` holds (HitboxCombo.cs:87-98).
/// A form row's flags, and whether it publishes the form's pose this sync.
/// DetPhysics syncs every registered collider to its FixTransform each
/// Simulate, a deactivated form's included (DetPhysics.cs:2498-2530). That
/// transform moves only while the form is live and on the pass it leaves, so
/// the row publishes while the form is live, at the first sync since it was
/// entered (a form left in that same pass never showed active), and at the
/// first sync after its last live one. EnterAbility gave the form its owner.
fn sync_form_row(row: &mut CEntity, flags: u32, live: bool, entered: bool, owner: u32) -> bool {
    let was_active = row.flags & E_ACTIVE != 0;
    row.flags = flags;
    if live || entered {
        row.owner = owner;
    }
    live || entered || was_active
}

/// A trigger box row's centre, zero velocity and axes, converted together:
/// the eight fields lie in a row and `raw_array` packs them.
fn set_box_row(row: &mut CEntity, center: Vec2, right: Vec2, up: Vec2) {
    [row.x, row.y, row.vx, row.vy, row.right_x, row.right_y, row.up_x, row.up_y] =
        Fix::raw_array([center.x, center.y, Fix::ZERO, Fix::ZERO, right.x, right.y, up.x, up.y]);
}

/// A row's centre and velocity, converted together like `set_box_row`'s.
fn set_moving_row(row: &mut CEntity, center: Vec2, velocity: Vec2) {
    [row.x, row.y, row.vx, row.vy] = Fix::raw_array([center.x, center.y, velocity.x, velocity.y]);
}

/// A GunTransform form's row (FreezeRayGun, Blink, the scale rays and the
/// Duplicator); `offset` is its authored collider offset.
#[allow(clippy::too_many_arguments)]
fn gun_form_row(
    entities: &mut [CEntity],
    inverse_extents: &[Vec2],
    slot: &PlayerSlot,
    gun_e: usize,
    gun: ActiveAbility,
    offset: Vec2,
    alive: bool,
    entered: usize,
    exit_position: Vec2,
) {
    let active = slot.active == gun;
    let row = &mut entities[gun_e];
    let flags = form_box_flags(alive && active);
    if sync_form_row(row, flags, active, entered == gun_e, slot.base.id) {
        // GunTransform only writes `body.up` from the aim while the
        // shot is pending (GunTransform.cs:184-192) and once more
        // inside Fire (GunTransform.cs:120-121); afterwards the form
        // keeps the orientation it fired at. The DetPhysics-synced
        // body rotation already carries that latch. Once out, the
        // form's FixTransform is where its exit left it: zeroed by
        // GunTransform.ExitAbility (GunTransform.cs:86), aimed when
        // FreezeRayGun went straight to Ability.ExitAbility
        // (FreezeRayGun.cs:128), turned again by a Fire that follows
        // DropPlatformTest's exit (GunTransform.cs:147-151).
        let s = slot.entity_slot(gun_e);
        // DPhysicsBox translates its authored offset with the
        // exact FixTransform basis copied/assigned by GunTransform,
        // while its axes are rebuilt from the scalar angle.
        let at_sync = slot.forms[s].synced;
        let root = if active { at_sync.position } else { exit_position };
        let rotation = at_sync.orientation.rotation();
        let offset_basis = at_sync.orientation.up().perp_cw();
        let basis = Vec2::angle(rotation);
        let offset = slot.gun_offset(s, offset);
        let center = root + offset_basis.complex_mul(offset);
        let collider = stored_box(center, basis, inverse_extents[gun_e]);
        set_box_row(row, center, collider.right, collider.up);
        row.rotation = rotation.raw();
    }
}

/// The Rock's circle row. `live` is the slime alive in its Rock form.
fn rock_row(circle: &mut CEntity, slot: &PlayerSlot, live: bool, entered: bool, exit_position: Vec2) {
    let rocking = slot.active == ActiveAbility::Rock;
    let flags = if live { E_ACTIVE | E_ENABLED } else { E_ENABLED };
    let publish = sync_form_row(circle, flags, rocking, entered, slot.base.id);
    // A Blink tunnel or teleport disables the Rock's GameObject,
    // so its body stops, but the collider still follows the
    // transform the tunnel moves, at the Player.Scale an earlier
    // Ability.UpdateSim this pass gave it.
    if slot.blink_tunnel_active || slot.teleport_effect_active {
        if rocking {
            circle.x = slot.base.position.x.raw();
            circle.y = slot.base.position.y.raw();
            circle.radius = slot.rock_circle().circle_radius.raw();
        }
    } else if publish {
        // BounceBall.ExitAbility leaves the Rock's FixTransform
        // where its body ended (BounceBall.cs:231-240), and
        // DetPhysics syncs the deactivated box there.
        let position = if rocking { slot.base.position } else { exit_position };
        set_moving_row(circle, position, slot.rock.body.velocity);
        circle.radius = slot.rock_circle().circle_radius.raw();
        circle.rotation = slot.rock.body.orientation.raw();
        circle.angular_velocity = slot.rock.body.angular_velocity.raw();
        circle.inverse_mass = slot.rock.body.inverse_mass.raw();
    } else if let Some(s) = slot.form_entities.iter().position(|&e| e == slot.rock_entity) {
        // DetPhysics keeps syncing the deactivated FixTransform:
        // BounceBall.ExitAbility zeroed its rotation, a
        // FreezeRayGun calling Ability.ExitAbility directly kept it
        // (FreezeRayGun.cs:128). A Rock a pickup took the slot of
        // keeps its row as it was.
        circle.rotation = slot.forms[s].pose.orientation.rotation().raw();
    }
}

/// A form box's flags: a trigger, active while its form is live.
fn form_box_flags(active: bool) -> u32 {
    if active {
        E_ACTIVE | E_ENABLED | E_TRIGGER
    } else {
        E_ENABLED | E_TRIGGER
    }
}

/// Most slimes hold no Drill in the cast slot; their call stops at the
/// three row checks, before the placement's setup.
#[inline(always)]
fn place_drill_hitbox_rows(
    entities: &mut [CEntity],
    inverse_extents: &[Vec2],
    slot: &PlayerSlot,
    data: &data::RolloutData,
) {
    if slot.drill_hitbox_entities[slot.active_slot].iter().any(|&entity| entity != usize::MAX) {
        place_drill_hitbox_rows_held(entities, inverse_extents, slot, data);
    }
}

#[inline(never)]
fn place_drill_hitbox_rows_held(
    entities: &mut [CEntity],
    inverse_extents: &[Vec2],
    slot: &PlayerSlot,
    data: &data::RolloutData,
) {
    // The three boxes share the Drill's pose; Fix arithmetic is pure, so the
    // basis and the angle's axes are built once.
    let basis = slot.drill.hitbox_up.perp_cw();
    let axes = Vec2::angle(slot.drill.hitbox_rotation);
    for (hitbox_index, &entity) in slot.drill_hitbox_entities[slot.active_slot].iter().enumerate() {
        if entity == usize::MAX {
            continue;
        }
        let row = &mut entities[entity];
        let (offset, _) = data.drill.hitboxes[hitbox_index];
        let scale = slot.drill_hitbox_scales[slot.active_slot][hitbox_index];
        let scale = if scale == Fix::ZERO { hurtbox_scale(slot.player_scale) } else { scale };
        let center = slot.drill.hitbox_position + (offset * scale).complex_mul(basis);
        let collider = stored_box(center, axes, inverse_extents[entity]);
        row.x = center.x.raw();
        row.y = center.y.raw();
        row.right_x = collider.right.x.raw();
        row.right_y = collider.right.y.raw();
        row.up_x = collider.up.x.raw();
        row.up_y = collider.up.y.raw();
        row.rotation = slot.drill.hitbox_rotation.raw();
    }
}

