const REWIND_CAPACITY: usize = 188;
const REWIND_MAX_SEGMENTS: usize = 15;
const REWIND_ARC_SAMPLES: usize = REWIND_MAX_SEGMENTS * 8 + 1;

#[derive(Clone, Copy, Default)]
pub struct RewindSample {
    pub position: Vec2,
    pub velocity: Vec2,
    pub external_velocity: Vec2,
    pub rotation: Fix,
    pub cooldowns: [Fix; 3],
}

#[derive(Clone)]
pub struct RewindState {
    pub ring: [RewindSample; REWIND_CAPACITY],
    pub head: usize,
    pub count: usize,
    pub rewinding: bool,
    pub playback_ticks: u32,
    pub playback_tick: u32,
    pub ability_slot: usize,
    /// wasPhysicsEnabled: PlayerPhysics.enabled as BeginRewind found it,
    /// restored by ReleaseControl (RewindRecorder.cs:149, 355).
    pub was_physics_enabled: bool,
    pub finish_next_tick: bool,
    /// The slime started this pass inside a form. Its GameObject was still
    /// inactive when RewindRecorder ran, so a form exiting later in the pass
    /// contributes no sample.
    pub in_form_at_pass: bool,
    pub destination: RewindSample,
    pub path_segments: usize,
    pub path_positions: [Vec2; REWIND_MAX_SEGMENTS + 1],
    pub path_rotations: [Fix; REWIND_MAX_SEGMENTS + 1],
    pub arc_lengths: [Fix; REWIND_ARC_SAMPLES],
    pub arc_count: usize,
    pub total_arc_length: Fix,
}

impl Default for RewindState {
    fn default() -> Self {
        Self {
            ring: [RewindSample::default(); REWIND_CAPACITY],
            head: 0,
            count: 0,
            rewinding: false,
            playback_ticks: 0,
            playback_tick: 0,
            ability_slot: 0,
            was_physics_enabled: false,
            finish_next_tick: false,
            in_form_at_pass: false,
            destination: RewindSample::default(),
            path_segments: 0,
            path_positions: [Vec2::ZERO; REWIND_MAX_SEGMENTS + 1],
            path_rotations: [Fix::ZERO; REWIND_MAX_SEGMENTS + 1],
            arc_lengths: [Fix::ZERO; REWIND_ARC_SAMPLES],
            arc_count: 0,
            total_arc_length: Fix::ZERO,
        }
    }
}

impl RewindState {
    fn push(&mut self, sample: RewindSample) {
        self.ring[self.head] = sample;
        self.head = (self.head + 1) % REWIND_CAPACITY;
        self.count = (self.count + 1).min(REWIND_CAPACITY);
    }

    fn sample_back(&self, ticks: usize) -> RewindSample {
        self.ring[(self.head + REWIND_CAPACITY - 1 - ticks) % REWIND_CAPACITY]
    }

    fn evaluate_spline(&self, t: Fix) -> (Vec2, Fix) {
        let s = t * Fix::from_int(self.path_segments as i64);
        let segment = (s.to_int().max(0) as usize).min(self.path_segments - 1);
        let u = s - Fix::from_int(segment as i64);
        let p0 = self.path_positions[segment.saturating_sub(1)];
        let p1 = self.path_positions[segment];
        let p2 = self.path_positions[segment + 1];
        let p3 = self.path_positions[(segment + 2).min(self.path_segments)];
        let u2 = u * u;
        let u3 = u2 * u;
        let half = Fix::from_f32(0.5);
        let position = half
            * (Fix::from_int(2) * p1
                + (p2 - p0) * u
                + (Fix::from_int(2) * p0 - Fix::from_int(5) * p1 + Fix::from_int(4) * p2 - p3)
                    * u2
                + (Fix::from_int(3) * (p1 - p2) + p3 - p0) * u3);
        let rotation =
            self.path_rotations[segment] * (Fix::ONE - u) + self.path_rotations[segment + 1] * u;
        (position, rotation)
    }

    fn evaluate_path(&self, t: Fix) -> (Vec2, Fix) {
        if self.total_arc_length <= Fix::ZERO {
            return self.evaluate_spline(t);
        }
        let target = t * self.total_arc_length;
        let mut lo = 0usize;
        let mut hi = self.arc_count - 1;
        while hi - lo > 1 {
            let mid = (lo + hi) / 2;
            if self.arc_lengths[mid] <= target {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        let span = self.arc_lengths[hi] - self.arc_lengths[lo];
        let fraction = if span > Fix::ZERO {
            (target - self.arc_lengths[lo]) / span
        } else {
            Fix::ZERO
        };
        self.evaluate_spline(
            (Fix::from_int(lo as i64) + fraction) / Fix::from_int((self.arc_count - 1) as i64),
        )
    }

    fn begin(&mut self, position: Vec2, rotation: Fix, ability_slot: usize) -> bool {
        if self.rewinding || self.count < 2 {
            return false;
        }
        let ticks_back = 150usize.min(self.count - 1);
        self.playback_ticks = ((ticks_back * 17) / 25).max(1) as u32;
        self.playback_tick = 0;
        self.ability_slot = ability_slot;
        self.finish_next_tick = false;
        self.destination = self.sample_back(ticks_back);
        self.path_segments = (ticks_back / 10).max(1);
        self.path_positions[0] = position;
        self.path_rotations[0] = rotation;
        for i in 1..=self.path_segments {
            let sample = self.sample_back(ticks_back * i / self.path_segments);
            self.path_positions[i] = sample.position;
            self.path_rotations[i] = sample.rotation;
        }
        self.arc_count = self.path_segments * 8 + 1;
        self.arc_lengths[0] = Fix::ZERO;
        let mut previous = self.path_positions[0];
        for i in 1..self.arc_count {
            let t = Fix::from_int(i as i64) / Fix::from_int((self.arc_count - 1) as i64);
            let current = self.evaluate_spline(t).0;
            self.arc_lengths[i] = self.arc_lengths[i - 1] + (current - previous).length();
            previous = current;
        }
        self.total_arc_length = self.arc_lengths[self.arc_count - 1];
        self.rewinding = true;
        true
    }
}

/// A platform spawned by the Platform ability (ResizablePlatform prefab).
/// Each PlatformTransform instance keeps at most one (its one-slot
/// srrBuffer); a re-cast from that instance removes the previous platform.
#[derive(Clone, Copy, Default)]
pub struct SpawnedPlatform {
    pub active: bool,
    /// ResizablePlatform.RemovePlatform keeps the body live while shrinking.
    pub being_removed: bool,
    /// The PlatformTransform holding it in its srrBuffer, as (player index,
    /// ability slot); None once that ability instance is destroyed.
    pub buffer: Option<(usize, usize)>,
    /// Index into `RolloutWorld::platforms` (kept in sync on removal).
    pub platform_index: usize,
    pub removal_time: Fix,
    pub removal_extents: Vec2,
    pub removal_radius: Fix,
    /// Its UpdateSim reached the removal curve's final key and called
    /// DestroyFix this pass.
    pub destroy_pending: bool,
    /// First updater hierarchy number of the platform prefab.
    pub hierarchy_base: u32,
}

/// DetPhysics body plus AnimateVelocity state for one rounded platform.
#[derive(Clone, Copy, Default)]
pub struct PlatformDynamics {
    pub body: Body,
    /// Its prefab's registration list (`World::register_prefab`), the
    /// script execution order of each, and its collider's number in it. Its
    /// row's HierarchyNumber less that one is what every number in the list
    /// registered offset by, which a copy made while it is out of the
    /// hierarchy keeps (ShootDuplicator.cs:709-718).
    pub registered: (&'static [u32], &'static [i32], u32),
    /// DPhysicsRoundedRect.Scale and its authored lower clamp. MachoThrow2
    /// mutates these while excavating a Boulder from the attached platform.
    pub scale: Fix,
    /// BoplBody.prevScale. Non-resizable bodies update inverse mass and
    /// inertia on the updater pass after DPhysics changes FixTransform scale.
    pub body_scale: Fix,
    pub body_resizable: bool,
    /// The platform BoplBody's magnet hold; only a Boulder's is ever held.
    pub hold: Hold,
    /// GameSessionHandler keeps authored grounds active but disables their
    /// colliders/AnimateVelocity until the shared level-intro routine ends.
    pub intro_disabled: bool,
    /// DPhysicsRoundedRect.MinScale and MaxScale, the bounds its Scale setter
    /// clamps to: serialized per platform (MaxScale 3 on some space maps).
    pub min_scale: Fix,
    pub max_scale: Fix,
    /// StickyRoundedRectangle.baseScaleForPlatform (GrowOnStart.scaleUp) and
    /// DPhysicsRoundedRect.timeSinceLastScaledUp: a platform grown past its
    /// base shrinks back ten seconds after its last growth.
    pub base_scale: Fix,
    pub time_since_scaled_up: Fix,
    /// StickyRoundedRectangle.UpdateBounds follows its collider updater on
    /// the pass after a later MachoThrow2 scale write.
    pub surface_shape_dirty: bool,
    /// The rounded rectangle's own serialized body. `body` becomes the
    /// effective CompositeBody while SpikeAttack children are attached; the
    /// observation bridge still exports this child body unchanged.
    pub root_body: Body,
    pub attached_children: u32,
    /// Children attached so far, including departed ones; stamps
    /// `attach_order`.
    pub attach_count: u32,
    /// CompositeBody.position is separate from the rounded-rectangle child
    /// centre. Box/RR positional correction can move the former without
    /// moving the latter until a later operation rebuilds the composite.
    pub composite_position: Vec2,
    /// FixTransform rotation written by a component this tick.
    /// DetPhysics.Simulate copies it into the body only after AnimateVelocity
    /// has computed its torque against the stale orientation
    /// (DetPhysics.cs:2504-2506).
    pub transform_rotation: Option<Fix>,
    /// Tick on which Updater adds a body registered mid-tick and calls
    /// AnimateVelocity.Init (Updater.cs:265-273): the spring homes on the
    /// position physics had already corrected on the spawn tick; 0 for
    /// none (a pending one is a pass after its spawn pass, never 0), so
    /// `init_tick > tick` is the whole "joins on a later pass" test.
    pub init_tick: u32,
    /// `platform_defs`' entry for it as the definition itself (None for
    /// `usize::MAX`): a copy keeps its source's with the index.
    pub definition: Option<&'static data::PlatformDef>,
    /// The prefab whose component order runs the platform's updaters.
    pub prefab: PlatformPrefab,
    /// That prefab's updaters, `PlatformUpdater::pack`ed: what
    /// `platform_updater_order` reads, kept per platform for its turn.
    pub updaters: u64,
    /// The pass Updater appended the platform's components: 0 for an
    /// authored one, else the pass after it was instantiated, whose Init walk
    /// takes them off Updater's queue (Updater.cs:258-287).
    pub appended: u32,
    /// DuplicatePlatformEffect asks AnimateVelocity to suppress its home
    /// spring on the next pass and re-home at the displaced body position.
    pub float_next_frame: bool,
    /// This pass's AnimateVelocity step: its tick, the impulse it added, the
    /// impulse it would have added floating, and the position it read.
    pub spring_step: Option<(u32, Vec2, Vec2, Vec2)>,
    /// The rect body's inverse mass before this pass's BoplBody rescale, and
    /// the tick: a Black Hole registered before a Duplicator copy pulls it
    /// first, with that mass (BlackHole.cs:434, BoplBody.cs:332-343).
    pub unscaled_inverse_mass: Option<(u32, Fix)>,
    /// AnimateVelocity.isBeingControlled: set by a Push on it, cleared only
    /// when that Push leaves through its own ExitAbility or by Initialize
    /// (ControlPlatform.cs:120-130,160-166; AnimateVelocity.cs:88-93).
    pub being_controlled: bool,
    pub home_position: Vec2,
    pub home_rotation: Fix,
    pub speed: Fix,
    pub mu: Fix,
    pub rotation_speed: Fix,
    /// `One - rotationMu`, AnimateVelocity's per-pass angular damping
    /// factor: rotationMu is constant per body, so its complement is kept.
    pub rotation_keep: Fix,
    pub interpolate_rotation_home: bool,
    /// ShakablePlatform's transform-space displacement. Meteor writes the
    /// request after this map updater has run, so the first sample is taken
    /// on the following pass.
    pub shake_time: Fix,
    pub shake_duration: Fix,
    pub shake_amount: Fix,
    pub shake_previous: Vec2,
    pub meteor_shake_curve: bool,
    /// `AnimateVelocity.randomSuddenDeathDelay`, drawn when the body enters
    /// sudden death; `None` until then (`inSuddenDeath`).
    pub sudden_death_delay: Option<Fix>,
    /// Permanent Duplicator copies are keyed by the casting gun hierarchy.
    /// A later copy from the same gun schedules the previous one to expire.
    pub duplicate_spawner_hierarchy: Option<u32>,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
    /// DPhysicsRoundedRect.startRadius: the radius the collider was built
    /// with, which `AsRoundedRect` still reports after the body is resized.
    pub start_radius: Fix,
    /// StickyRoundedRectangle.DropAllAttachedPlayers. The platform updater
    /// decrements this before player prefabs run; a Meteor landing writes two
    /// after that updater, so later players can be ejected immediately and
    /// earlier players see the remaining frame on the following pass.
    pub drop_players_frames: i8,
    pub dont_drop_player_id: u32,
    pub drop_force: Fix,
    /// A wall QuantumTunnel is registered on the shot pass, waits one strict
    /// second, disables its victim for four seconds, then restores it.
    pub blink_tunnel_active: bool,
    pub blink_tunnel_appended: u32,
    pub blink_tunnel_initialized: bool,
    pub blink_tunnel_delay: Fix,
    pub blink_tunnel_age: Fix,
    /// The tunnel's updater slot: spawned updaters created after it (a
    /// Black Hole) see the wall it restores on the same pass.
    pub blink_tunnel_hierarchy: u32,
    /// The basis and box axes of the last integration: a platform that
    /// translates without rotating (sudden death, a spring settling) keeps
    /// its basis instead of consulting the sine table twice.
    pub basis: Option<PlatformBasis>,
}

/// `Vec2::angle(orientation)` and the rounded rectangle's box axes on it
/// (Box.SetRotation), kept from one integration to the next. A turn small
/// enough to leave both sine-table entries alone leaves the basis, and an
/// unchanged basis and `inverse_extents` the axes.
#[derive(Clone, Copy)]
pub struct PlatformBasis {
    orientation: Fix,
    /// `fast_cos_entry` and `fast_sin_entry` of the orientation.
    entries: [u64; 2],
    basis: Vec2,
    /// The `inverse_extents` bits `right` and `up` were built from.
    inverse_extents: [u64; 2],
    right: Vec2,
    up: Vec2,
}

impl PlatformDynamics {
    /// The basis of the body's orientation and the box axes it gives a box
    /// of `inverse_extents`: `Vec2::angle(orientation)`,
    /// `(RIGHT / inverse_extents.x).complex_mul(basis)` and
    /// `(UP / inverse_extents.y).complex_mul(basis)`.
    #[inline(always)]
    fn basis_axes(&mut self, inverse_extents: Vec2) -> (Vec2, Vec2, Vec2) {
        let orientation = self.body.orientation;
        let bits = [inverse_extents.x.bits(), inverse_extents.y.bits()];
        let axes = |basis: Vec2| {
            (
                (Vec2::RIGHT / inverse_extents.x).complex_mul(basis),
                (Vec2::UP / inverse_extents.y).complex_mul(basis),
            )
        };
        if !matches!(self.basis, Some(cached) if cached.orientation == orientation) {
            let entries = [orientation.fast_cos_entry(), orientation.fast_sin_entry()];
            match &mut self.basis {
                Some(cached) if cached.entries == entries => cached.orientation = orientation,
                slot => {
                    let basis = Vec2::new(Fix::fast_sin_at(entries[0]), Fix::fast_sin_at(entries[1]));
                    let (right, up) = axes(basis);
                    *slot = Some(PlatformBasis { orientation, entries, basis, inverse_extents: bits, right, up });
                }
            }
        }
        let Some(cached) = &mut self.basis else { unreachable!() };
        if cached.inverse_extents != bits {
            (cached.right, cached.up) = axes(cached.basis);
            cached.inverse_extents = bits;
        }
        #[cfg(debug_assertions)]
        {
            let bits = |v: Vec2| [v.x.to_f64().to_bits(), v.y.to_f64().to_bits()];
            let basis = Vec2::angle(orientation);
            debug_assert_eq!(bits(cached.basis), bits(basis));
            debug_assert_eq!(bits(cached.right), bits((Vec2::RIGHT / inverse_extents.x).complex_mul(basis)));
            debug_assert_eq!(bits(cached.up), bits((Vec2::UP / inverse_extents.y).complex_mul(basis)));
        }
        (cached.basis, cached.right, cached.up)
    }
}

/// PlatformTransform.State.
pub const PLATFORM_ANTICIPATION: u32 = 0;
pub const PLATFORM_ROTATION: u32 = 1;
pub const PLATFORM_SIZE: u32 = 2;
pub const PLATFORM_EXIT: u32 = 3;

/// An ability slot's form object, which outlives each use. Its box collider
/// and PlayerPhysics follow Player.Scale on their own. Ability assigns the
/// scale to the box every pass, which divides the inverse extents its row
/// holds by the rounded `(One / old) * new`, and PlayerPhysics.UpdateScale
/// multiplies its body's radius by `new / prevScal`, so the drift carries
/// over. A zero scale marks a form that has not been entered yet.
#[derive(Clone, Debug, Default)]
pub struct FormBody {
    /// The form's PlayerPhysics and PlayerBody while it is inactive. While it
    /// is live they are `PlayerSlot::base`: they move in at entry and back
    /// out at exit.
    pub body: Player,
    pub scale: Fix,
    /// FixTransform.offset, which SetScale_DPhysicsOnly multiplies by
    /// `new / old` (FixTransform.cs:99-103).
    pub offset: Vec2,
    /// A circle form's DPhysicsCircle.radius, which its Scale setter
    /// multiplies by `(1 / old) * new` (DPhysicsCircle.cs:214-221).
    pub circle_radius: Fix,
    /// The Rock circle's startRadius (GetStartRadius, DPhysicsCircle.cs:372):
    /// the Scale setter rescales it until ManualInit registers the circle,
    /// and it stays from then on (DPhysicsCircle.cs:186-205, 292-299).
    pub start_radius: Fix,
    /// A form BoplBody's DetPhysics inverse mass and inertia, and the
    /// prevScale it last divided them by; zero until the body first runs.
    pub inverse_mass: Fix,
    pub inverse_inertia: Fix,
    pub mass_scale: Fix,
    /// A form BoplBody's DetPhysics force while the form is out: what was
    /// added after its last integration, which the next one applies. Only
    /// the Rock's body takes forces.
    pub force: Vec2,
    /// A form BoplBody's magnet hold; only the Rock's is ever held.
    pub hold: Hold,
    /// The form's FixTransform, which DetPhysics syncs its box from whether
    /// the form is casting, hidden by a teleport or gone inactive.
    pub pose: FormPose,
    /// The FixTransform the form's box took at the last SyncAll: the body's
    /// while the form is live, `pose` once it is out (DetPhysics.cs:2517-2524).
    pub synced: FormPose,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct FormPose {
    pub position: Vec2,
    pub orientation: Orientation,
}

/// `Scale = value` on a box collider whose Scale is `scale` (zero for one
/// never scaled): every form prefab's box clamps it to MinScale (Fix)0.3f,
/// above Player.Scale's own (Fix)0.3 floor. The setter divides the box's
/// inverseExtents, which its row's entry holds, right then
/// (DPhysicsBox.cs:212-214).
fn scale_box(scale: &mut Fix, value: Fix, inverse_extents: &mut Vec2) {
    let value = hurtbox_scale(value);
    let old = if *scale == Fix::ZERO { Fix::ONE } else { *scale };
    *inverse_extents = *inverse_extents / ((Fix::ONE / old) * value);
    *scale = value;
}

impl FormBody {
    /// The form object of `ability` before its first entry, as its prefab's
    /// Awake leaves it: its PlayerBody's simulated (Push.prefab's is off, so
    /// that body never takes a turn, PlayerBody.cs:107-112) and its own
    /// PlayerPhysics' serialized constants and radius with prevScal One
    /// (PlayerPhysics.cs:39); none for a form without a PlayerPhysics.
    fn unentered(ability: u32) -> FormBody {
        let data = data::get().abilities.get(ability as usize);
        let simulated = data.and_then(|data| data.body_simulated).unwrap_or(true);
        let mut body = Player { simulated, physics_enabled: true, ..Player::default() };
        if let Some(data) = data.filter(|data| data.constants.is_some()) {
            body.constants = data.constants.clone().unwrap();
            body.radius = data.physics_radius;
            body.physics_scale = Fix::ONE;
        }
        FormBody { body, ..FormBody::default() }
    }

    /// `potentialCollider.Scale = Player.Scale` (Ability.cs:105, 135).
    fn set_scale(&mut self, value: Fix, inverse_extents: &mut Vec2) {
        if self.scale == Fix::ZERO {
            *self = FormBody {
                body: std::mem::take(&mut self.body),
                scale: Fix::ONE,
                pose: self.pose,
                synced: self.synced,
                ..FormBody::default()
            };
        }
        scale_box(&mut self.scale, value, inverse_extents);
    }

    /// `set_scale` for a box collider with an offset.
    fn set_scale_offset(&mut self, value: Fix, offset: Vec2, inverse_extents: &mut Vec2) {
        let value = hurtbox_scale(value);
        let fresh = self.scale == Fix::ZERO;
        let old = if fresh { Fix::ONE } else { self.scale };
        self.set_scale(value, inverse_extents);
        if fresh {
            self.offset = offset;
        }
        self.offset = self.offset * (value / old);
    }

    /// `potentialCollider.Scale = Player.Scale` for a circle form, clamped to
    /// the prefab's MinScale (Fix)0.3f and MaxScale 3.
    fn set_circle_scale(&mut self, value: Fix, radius: Fix) {
        if self.scale == Fix::ZERO {
            *self = FormBody {
                body: std::mem::take(&mut self.body),
                scale: Fix::ONE,
                circle_radius: radius,
                pose: self.pose,
                synced: self.synced,
                ..FormBody::default()
            };
        }
        let value = hurtbox_scale(value);
        self.circle_radius *= (Fix::ONE / self.scale) * value;
        self.scale = value;
    }

    /// `set_circle_scale` for a circle whose FixTransform carries an
    /// offset, which SetScale_DPhysicsOnly multiplies by `new / old`.
    fn set_circle_scale_offset(&mut self, value: Fix, radius: Fix, offset: Vec2) {
        let fresh = self.scale == Fix::ZERO;
        let old = if fresh { Fix::ONE } else { self.scale };
        self.set_circle_scale(value, radius);
        if fresh {
            self.offset = offset;
        }
        self.offset = self.offset * (self.scale / old);
    }

    /// DPhysicsCircle.Scale's setter on a circle with its own bounds.
    fn write_circle_scale(&mut self, value: Fix, min: Fix, max: Fix) {
        let value = value.clamp(min, max);
        self.circle_radius *= (Fix::ONE / self.scale) * value;
        self.scale = value;
    }

    /// BoplBody.UpdateSim: a body's DetPhysics mass follows its collider's
    /// Scale, multiplied by prevScale / Scale on each change (BoplBody.cs:332-343).
    /// The collider keeps it between uses of the form.
    fn follow_body_mass(&mut self, body: &mut crate::physics::Body) {
        if self.mass_scale == Fix::ZERO {
            self.inverse_mass = body.inverse_mass;
            self.inverse_inertia = body.inverse_inertia;
            self.mass_scale = Fix::ONE;
        }
        if self.mass_scale != self.scale {
            let ratio = self.mass_scale / self.scale;
            self.inverse_mass *= ratio;
            self.inverse_inertia *= ratio;
            self.mass_scale = self.scale;
        }
        body.inverse_mass = self.inverse_mass;
        body.inverse_inertia = self.inverse_inertia;
    }
}

/// Box.SetRotation: a box's axes rebuilt from the inverseExtents it stores
/// (Box.cs:30-35).
fn stored_box(center: Vec2, basis: Vec2, inverse_extents: Vec2) -> OrientedBox {
    OrientedBox {
        center,
        right: (Vec2::RIGHT / inverse_extents.x).complex_mul(basis),
        up: (Vec2::UP / inverse_extents.y).complex_mul(basis),
        inverse_extents,
    }
}

