/// MagnetGun's animation, pull state and allocation-free held-object handle.
#[derive(Clone, Copy, Default)]
pub struct MagnetState {
    /// MagnetState: 1 prepulling, 2 pulling, 4 paused, 5 exiting.
    pub phase: u8,
    /// Active SpriteAnimator clip: 0 enter, 1 prepull, 2 idle, 3 exit.
    pub animation: u8,
    pub animation_ticks: u32,
    pub time_spent_pulling: Fix,
    pub aim: Vec2,
    pub has_fired: bool,
    pub held: MagnetHeld,
    /// The held object's hierarchy, which tells it from a later object in
    /// its pool slot (`RolloutWorld::magnet_held_base`).
    pub held_base: u32,
    pub held_position: Vec2,
    /// TryPickupNearbyItems contributes this cast-pass circle to MagnetGun's
    /// allocation-free StaticUpdate parry sweep.
    pub parry_registered: bool,
    pub parry_circle: Circle,
}

impl MagnetState {
    /// MagnetGun.enterPull: pulling, on a fresh idle animation
    /// (MagnetGun.cs:335-342).
    fn enter_pull(&mut self) {
        self.phase = 2;
        self.animation = 2;
        self.animation_ticks = 0;
    }

    /// MagnetGun.enterPause: paused, holding nothing, on a fresh idle
    /// animation, which has no callback to leave the pause (MagnetGun.cs:344-354).
    fn enter_pause(&mut self) {
        self.phase = 4;
        self.held = MagnetHeld::Nothing;
        self.animation = 2;
        self.animation_ticks = 0;
    }
}

